-- =====================================================
-- CATALOGO REAL DE DELIVERY LOCAL - IMPORTADO DE EXCEL
-- Fuente: menu_completoo.xlsx | Hoja1 | filas 2 a 74
-- 6 negocios, 73 productos, 17 categorias, 37 variantes y 21 puntos institucionales
-- Reejecutable: identifica registros por nombre/fila de origen.
-- =====================================================
USE cutlaquepaque_delivery;
START TRANSACTION;

UPDATE negocios SET activo=FALSE WHERE nombre IN ('Tamales Mary', 'Tacos Beny', 'Fonda de Lety', 'Lonches Mario', 'Aguas Frescas La Michoacana');
UPDATE productos p INNER JOIN negocios n ON n.id_negocio=p.id_negocio SET p.disponible=FALSE WHERE n.nombre IN ('Tamales Mary', 'Tacos Beny', 'Fonda de Lety', 'Lonches Mario', 'Aguas Frescas La Michoacana') AND p.fila_excel IS NULL;

-- RESPONSABLES / VENDEDORES
INSERT INTO vendedores (nombre,telefono,correo)
SELECT x.nombre,x.telefono,x.correo FROM (
  SELECT 'Luis Martínez' AS nombre, '33 1398 3400' AS telefono, 'contacto.laesquinadelsazon@gmail.com' AS correo
  UNION ALL SELECT 'LALO' AS nombre, '33 3915 9270.' AS telefono, 'No disponible' AS correo
  UNION ALL SELECT 'Jose Luis' AS nombre, '33 33552951.' AS telefono, 'MAKITOSGSHIGDL.COM.MX' AS correo
  UNION ALL SELECT 'lizzeth' AS nombre, '3318830325' AS telefono, 'no disponible' AS correo
  UNION ALL SELECT 'Miguel Hernandez' AS nombre, '33 1972 2004.' AS telefono, 'no disponible' AS correo
  UNION ALL SELECT 'Samantha Velazquez' AS nombre, '33 2947 8384.' AS telefono, 'paletasdani12gmail.com' AS correo
) AS x WHERE NOT EXISTS (SELECT 1 FROM vendedores v WHERE v.nombre=x.nombre AND COALESCE(v.telefono,'')=COALESCE(x.telefono,'') AND COALESCE(v.correo,'')=COALESCE(x.correo,''));

-- CATEGORIAS (se conserva la primera escritura de cada categoria)
INSERT INTO categorias (nombre)
SELECT x.nombre FROM (
  SELECT 'COMIDA' AS nombre
  UNION ALL SELECT 'BEBIDAS' AS nombre
  UNION ALL SELECT 'POSTRE' AS nombre
  UNION ALL SELECT 'pizzas' AS nombre
  UNION ALL SELECT 'entradas' AS nombre
  UNION ALL SELECT 'ensalada' AS nombre
  UNION ALL SELECT 'Hot Dog' AS nombre
  UNION ALL SELECT 'lonches' AS nombre
  UNION ALL SELECT 'hamburguesas' AS nombre
  UNION ALL SELECT 'snacks' AS nombre
  UNION ALL SELECT 'refresco y agua' AS nombre
  UNION ALL SELECT 'Paletas de Agua' AS nombre
  UNION ALL SELECT 'Paletas de Leche' AS nombre
  UNION ALL SELECT 'Aguas Frescas' AS nombre
  UNION ALL SELECT 'Nieves / Helados' AS nombre
  UNION ALL SELECT 'Sandwich / Helados' AS nombre
  UNION ALL SELECT 'Bebidas Preparadas / Frappuccinos' AS nombre
) AS x WHERE NOT EXISTS (SELECT 1 FROM categorias c WHERE LOWER(c.nombre)=LOWER(x.nombre));

-- NEGOCIOS
INSERT INTO negocios (id_vendedor,nombre,descripcion,direccion,telefono,horario_atencion,observaciones,logo_url,fila_fuente,activo)
SELECT v.id_vendedor,x.nombre,x.descripcion,x.direccion,x.telefono,x.horario,x.observaciones,NULL,x.fila_fuente,TRUE
FROM (
  SELECT 'La Esquina del Sazón' AS nombre,'Auténtica comida mexicana con sabor casero. Especialistas en pellizcadas, huaraches y tacos con ingredientes frescos y hechos al momento.' AS descripcion,'Avenida Paseo Cerro del Cuatro, Zapotlán esquina, Fovissste Miravalle, 45594 San Pedro Tlaquepaque, Jal.' AS direccion,'33 1398 3400' AS telefono,'Lunes a Sábado de 6:00 PM a 11:00 PM. Domingo cerrado.' AS horario,'Los pedidos grandes requieren al menos 1 hora de anticipación. Se acepta efectivo y transferencia.' AS observaciones,2 AS fila_fuente,'Luis Martínez' AS vendedor,'contacto.laesquinadelsazon@gmail.com' AS correo_vendedor
  UNION ALL SELECT 'Mariscos Lalo''S 1.' AS nombre,'Es un restaurante de mariscos que se describe como un negocio 100% familiar.' AS descripcion,'C. Juan de la Barrera 5371, El Campesino, 45597 San Pedro Tlaquepaque, Jal..' AS direccion,'33 3915 9270.' AS telefono,'Abierto de miércoles a lunes de 9 AM a 6 PM. Los días martes se encuentra cerrado' AS horario,'Servicio a domicilio limitado a 1 km a la redonda, prohibida la venta de cerveza sin alimentos, ambiente 100% familiar y servicio de rockola (3 canciones por $10.00).' AS observaciones,17 AS fila_fuente,'LALO' AS vendedor,'No disponible' AS correo_vendedor
  UNION ALL SELECT 'Makito sushi.' AS nombre,'Restaurante especializado en comida japonesa, sushi, sake y platillos orientales variados.' AS descripcion,'Tierra de los Tules #180, Local #5, Col. Terralta, C.P. 44990, San Pedro Tlaquepaque, Jal. (Ubicado en PLAZA AZTECA).' AS direccion,'33 33552951.' AS telefono,'Martes a Sábado de 1:00 PM a 9:30 PM; Domingo de 1:00 PM a 7:30 PM; Lunes cerrado.' AS horario,'Tierra de los Tules 180, Local 5, Col. Terralta, San Pedro Tlaquepaque, Jal.
   * Camellón principal frente a la glorieta del fraccionamiento Terralta 
   * Estacionamiento exterior sobre la avenida principal de Plaza Azteca' AS observaciones,35 AS fila_fuente,'Jose Luis' AS vendedor,'MAKITOSGSHIGDL.COM.MX' AS correo_vendedor
  UNION ALL SELECT 'MERAKI RESTAURANT PIZZERIA' AS nombre,'Pizzería y restaurante con menú estilo italiano, especializado en pizzas a la leña (base roja, blanca, veganas), entradas gourmet, ensaladas, alitas, postres y bebidas.' AS descripcion,'San Francisco 20-oriente, Nueva Santa María, 45530 San Pedro Tlaquepaque, Jal.' AS direccion,'3318830325' AS telefono,'Jueves, Domingo, Lunes y Martes de 4:00 PM a 11:00 PM; Viernes y Sábado de 4:00 PM a 12:00 AM (Media noche); Miércoles cerrado.' AS horario,'Pizzería y restaurante con menú estilo italiano, especializado en pizzas a la leña (base roja, blanca, veganas), entradas gourmet, ensaladas, alitas, postres y bebidas.' AS observaciones,46 AS fila_fuente,'lizzeth' AS vendedor,'no disponible' AS correo_vendedor
  UNION ALL SELECT 'Peinecillo''s Gril.' AS nombre,'Puesto/local de comida rápida y snacks especializado en hamburguesas, hot dogs, lonches, papas fritas y bebidas.' AS descripcion,'Av. Las Terrazas 981B, Las Terrazas, 45599 San Pedro Tlaquepaque, Jal.' AS direccion,'33 1972 2004.' AS telefono,'Lunes a Viernes de 6:00 PM a 10:30 PM; Sábado y Domingo de 2:00 PM a 10:30 PM.' AS horario,'Concepto de snacks a la parrilla con paquetes económicos que combinan hamburguesas con papas o salchichas.' AS observaciones,55 AS fila_fuente,'Miguel Hernandez' AS vendedor,'no disponible' AS correo_vendedor
  UNION ALL SELECT 'Paleteria Dani.' AS nombre,'Paletería tradicional que ofrece paletas de agua y de leche, aguas frescas, nieves, sándwiches de helado y bebidas preparadas como frappuccinos.' AS descripcion,'49990, Miravalle, 49990 Guadalajara, Jal.' AS direccion,'33 2947 8384.' AS telefono,'Lunes, Martes, Miércoles, Viernes y Sábado de 11:00 AM a 8:30 PM; Jueves de 11:00 AM a 8:00 PM; Domingo de 2:00 PM a 7:00 PM.' AS horario,'Ofrecen productos refrescantes tradicionales a precios muy accesibles y envasan sus propias aguas frescas bajo la etiqueta "Dani".' AS observaciones,65 AS fila_fuente,'Samantha Velazquez' AS vendedor,'paletasdani12gmail.com' AS correo_vendedor
) AS x
INNER JOIN vendedores v ON v.nombre=x.vendedor AND COALESCE(v.telefono,'')=COALESCE(x.telefono,'') AND COALESCE(v.correo,'')=COALESCE(x.correo_vendedor,'')
WHERE NOT EXISTS (SELECT 1 FROM negocios n WHERE n.nombre=x.nombre);

-- PRODUCTOS: se conserva una fila por producto del Excel, incluso nombres repetidos.
INSERT INTO productos (id_negocio,id_categoria,nombre,descripcion,precio,disponible,disponibilidad_texto,existencias_aproximadas,existencias_texto,variantes_texto,precios_variantes_texto,tiempo_preparacion_texto,imagen_url,fila_excel)
