  UNION ALL SELECT 'Paleteria Dani.' AS negocio, 'Piña/Amarilla' AS nombre, 'Agua Fresca (Piña/Amarilla): Bebida tradicional refrescante servida en botella de plástico de 1 litro.' AS descripcion, 20.0 AS precio, 1 AS disponible, 'Disponibles todos los días de la semana durante su horario de apertura (11:00 AM a 8:30 PM aprox, domingos horario reducido).' AS disponibilidad_texto, NULL AS existencias_aproximadas, 'No se especifican en las imágenes.' AS existencias_texto, '1-2. Paletas de Agua: Varios colores y sabores frutales.' AS variantes_texto, '16' AS precios_variantes_texto, '2minutos' AS tiempo_preparacion_texto, 69 AS fila_excel, 'Aguas Frescas' AS categoria
  UNION ALL SELECT 'Paleteria Dani.' AS negocio, 'Horchata/Blanca' AS nombre, 'Agua Fresca (Horchata/Blanca): Bebida dulce y fresca servida en envase de 1 litro.' AS descripcion, 20.0 AS precio, 1 AS disponible, 'Disponibles todos los días de la semana durante su horario de apertura (11:00 AM a 8:30 PM aprox, domingos horario reducido).' AS disponibilidad_texto, NULL AS existencias_aproximadas, 'No se especifican en las imágenes.' AS existencias_texto, '1-2. Paletas de Agua: Varios colores y sabores frutales.' AS variantes_texto, '25' AS precios_variantes_texto, '2minutos' AS tiempo_preparacion_texto, 70 AS fila_excel, 'Aguas Frescas' AS categoria
  UNION ALL SELECT 'Paleteria Dani.' AS negocio, 'Sabor Fresa/Rosa' AS nombre, 'Agua Fresca (Fresa/Rosa): Bebida frutal embotellada en presentación de 1 litro.' AS descripcion, 20.0 AS precio, 1 AS disponible, 'Disponibles todos los días de la semana durante su horario de apertura (11:00 AM a 8:30 PM aprox, domingos horario reducido).' AS disponibilidad_texto, NULL AS existencias_aproximadas, 'No se especifican en las imágenes.' AS existencias_texto, '1-2. Paletas de Agua: Varios colores y sabores frutales.' AS variantes_texto, '16' AS precios_variantes_texto, '2minutos' AS tiempo_preparacion_texto, 71 AS fila_excel, 'Aguas Frescas' AS categoria
  UNION ALL SELECT 'Paleteria Dani.' AS negocio, 'Nieve Bola Grande' AS nombre, 'Nieve Bola Grande: Porción abundante de helado servida en vaso de unicel rotulado con el logo del negocio.' AS descripcion, 20.0 AS precio, 1 AS disponible, 'Disponibles todos los días de la semana durante su horario de apertura (11:00 AM a 8:30 PM aprox, domingos horario reducido).' AS disponibilidad_texto, NULL AS existencias_aproximadas, 'No se especifican en las imágenes.' AS existencias_texto, '1-2. Paletas de Agua: Varios colores y sabores frutales.' AS variantes_texto, '25' AS precios_variantes_texto, '2minutos' AS tiempo_preparacion_texto, 72 AS fila_excel, 'Nieves / Helados' AS categoria
  UNION ALL SELECT 'Paleteria Dani.' AS negocio, 'Sandwich de vainilla' AS nombre, 'Sandwich de vainilla: Cuadro de helado de vainilla contenido entre dos galletas, envuelto en papel aluminio.' AS descripcion, 16.0 AS precio, 1 AS disponible, 'Disponibles todos los días de la semana durante su horario de apertura (11:00 AM a 8:30 PM aprox, domingos horario reducido).' AS disponibilidad_texto, NULL AS existencias_aproximadas, 'No se especifican en las imágenes.' AS existencias_texto, '1-2. Paletas de Agua: Varios colores y sabores frutales.' AS variantes_texto, '25' AS precios_variantes_texto, '2minutos' AS tiempo_preparacion_texto, 73 AS fila_excel, 'Sandwich / Helados' AS categoria
  UNION ALL SELECT 'Paleteria Dani.' AS negocio, 'Frappuccino' AS nombre, 'Frappuccino: Bebida helada mezclada tipo frappé, decorada con crema batida, chispas, jarabe de chocolate y una galleta en forma de tubo.' AS descripcion, 25.0 AS precio, 1 AS disponible, 'Disponibles todos los días de la semana durante su horario de apertura (11:00 AM a 8:30 PM aprox, domingos horario reducido).' AS disponibilidad_texto, NULL AS existencias_aproximadas, 'No se especifican en las imágenes.' AS existencias_texto, '1-2. Paletas de Agua: Varios colores y sabores frutales.' AS variantes_texto, '20' AS precios_variantes_texto, '2minutos' AS tiempo_preparacion_texto, 74 AS fila_excel, 'Bebidas Preparadas / Frappuccinos' AS categoria
) AS x
INNER JOIN negocios n ON n.nombre=x.negocio
LEFT JOIN categorias c ON LOWER(c.nombre)=LOWER(x.categoria)
WHERE NOT EXISTS (SELECT 1 FROM productos p WHERE p.id_negocio=n.id_negocio AND p.fila_excel=x.fila_excel);

